package org.sleepwell.app;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;
/** Temporal event acceptance, separate from clip amplitude and the opt-in cue's score/strength policy. */
public final class SoundSensitivityActivity extends Activity implements SoundSensitivitySave.Observer {
 private SoundSensitivity draft;private String readError="";private SoundSensitivitySave job;private SoundSensitivitySave.State operation;private Dialog picker;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);Object old=getLastNonConfigurationInstance();job=old instanceof SoundSensitivitySave?(SoundSensitivitySave)old:new SoundSensitivitySave(SoundSensitivitySettings.factory.open(getApplicationContext()));SoundSensitivitySettings.Read initial;try{initial=job.port.read();}catch(RuntimeException failure){initial=new SoundSensitivitySettings.Read(SoundSensitivity.DEFAULT,"Saved settings could not be read. Defaults are being used.");}draft=initial.policy;readError=initial.error;if(saved!=null){readError=saved.getString("readError",readError);try{draft=SoundSensitivityJson.decode(saved.getString("draft"));}catch(IllegalArgumentException invalid){draft=SoundSensitivity.DEFAULT;readError="Draft settings are invalid. Defaults are being used.";}}job.observe(this);}
 @Override public Object onRetainNonConfigurationInstance(){return job;}
 @Override public void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("draft",SoundSensitivityJson.encode(draft));out.putString("readError",readError);}
 @Override public void changed(SoundSensitivitySave.State state){if(isDestroyed())return;operation=state;if(state.busy&&state.policy!=null)draft=state.policy;if(state.saved)readError="";render();}
 private void render(){boolean busy=operation!=null&&operation.busy;LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);LinearLayout header=RecordUi.header(body,"Sound sensitivity",this::finish);header.setMinimumHeight(Design.dp(this,52));header.setLayoutParams(new LinearLayout.LayoutParams(-1,-2));Design.space(body,14);Design.text(body,"Minimum duration of accepted estimates. Applies next night.",14,400,Design.MUTED);Design.space(body,20);
  for(String key:SoundSensitivity.CATEGORIES){View row=Design.item(body,"wave",SoundSensitivity.label(key),SoundSensitivity.choice(draft.windows(key)),()->choose(key));row.setContentDescription("Minimum duration "+SoundSensitivity.label(key));RecordUi.enabled(row,!busy);Design.line(body);}
  Design.space(body,16);Design.text(body,"High keeps shorter events and can increase false detections. Model scores stay unchanged.",13,400,Design.MUTED);Design.space(body,8);View reset=Design.item(body,"undo","Restore defaults",null,()->{draft=SoundSensitivity.DEFAULT;render();});reset.setContentDescription("Restore sound sensitivity defaults");RecordUi.enabled(reset,!busy);
  LinearLayout footer=RecordUi.footer(body);String message=operation!=null&&!operation.error.isEmpty()?operation.error:readError;boolean saved=operation!=null&&operation.saved&&draft.equals(operation.policy);if(saved)message="Saved for the next night.";TextView status=Design.text(footer,message,13,500,message.isEmpty()?Design.MUTED:!readError.isEmpty()||operation!=null&&!operation.error.isEmpty()?0xffa93919:Design.BROWN);status.setContentDescription("Sound sensitivity status");status.setVisibility(message.isEmpty()?View.GONE:View.VISIBLE);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);View save=Design.button(footer,busy?"Saving…":"Save sensitivity",true,()->job.start(draft));RecordUi.enabled(save,!busy);
 }
 private void choose(String key){if(operation!=null&&operation.busy||picker!=null&&picker.isShowing())return;String[] values={"1 accepted window · about 1 sec (High)","2 accepted windows · about 2 sec (Default)","3 accepted windows · about 3 sec (Low)"};picker=SleepPicker.choices(this,SoundSensitivity.label(key)+" duration",values,draft.windows(key)-1,n->{draft=draft.with(key,n+1);render();});}
 boolean awaitWorkers(long timeout)throws InterruptedException{return job.awaitClosed(timeout);}
 @Override protected void onDestroy(){if(picker!=null)picker.dismiss();job.detach(this);if(!isChangingConfigurations())job.close();super.onDestroy();}
 @Override protected void onPostResume(){super.onPostResume();RecordUi.lightBars(this);}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
